from pathlib import Path
import json,copy,hashlib,sqlite3
P=Path(__file__).resolve().parent
s=json.loads((P/'source.json').read_text());a=json.loads((P/'answer.json').read_text());by={r['number']:r for r in a};sources={r['number']:r for r in s};out=[]
def fix(n,body,reason):
 r=copy.deepcopy(by[n]);r['proposed_xml']=body;r['reason']+=' Revue indépendante : '+reason;r['review_notes']+=' Correction sur édition examinée SHA 06d53565cf029c1a16470d2e4be3425115803c2055f63700190660a193565fec. '+reason;out.append(r)
fix('L1226-20',by['L1226-20']['proposed_xml'].replace("Les deuxième et dernier alinéas de l’article L. 1226-12 et les articles L. 1226-14 à L. 1226-16 ne leur sont pas applicables.","Les dispositions de l’article L. 1226-12 relatives aux cas de licenciement énumérés à ses 1° à 3° et à la procédure de licenciement pour motif personnel, ainsi que les articles L. 1226-14 à L. 1226-16, ne leur sont pas applicables."),"Le renvoi aux deuxième et dernier alinéas de L1226-12 était devenu erroné après la subdivision des cas en 1° à 3° ; leurs objets sont identifiés comme dans l’avant-image, sans retirer l’information écrite ni la règle de satisfaction du reclassement.")
fix('L1524-1',"<p>À Mayotte, le contrat de travail unique conclu à compter de l’entrée en vigueur de la loi instituant le contrat de travail unique relève des articles L. 1221-19 à L. 1221-26 : trois mois d’essai au plus, durées plus courtes applicables, aucun renouvellement et quinze jours calendaires de préavis pour chaque partie.</p><p>Pour les contrats conclus avant cette entrée en vigueur, les règles relatives à la période d’essai applicables lors de leur conclusion demeurent applicables. Elles comprennent, dans son champ temporel propre, la dérogation concernant les durées plus longues fixées par les accords collectifs de branche conclus avant le 1er janvier 2018, dans la limite d’une durée de cinq ans. Ce maintien ne prolonge ni ne rétablit une dérogation ou stipulation dont l’effet a déjà cessé.</p>","L’adaptation ancienne est autonome et bornée à son champ temporel ; elle ne vise plus le deuxième alinéa déplacé de L1221-22, désormais affecté aux accords plus courts du régime nouveau.")
# Isolated clarification: trial termination must not inherit registered-dismissal form.
fix('L1221-25',by['L1221-25']['proposed_xml'].replace("Ce préavis court selon l’article L. 1234-3.","La rupture est notifiée par tout moyen permettant d’établir sa réception par le salarié. Les quinze jours calendaires se comptent à partir du lendemain de cette réception et expirent à la fin du quinzième jour, même non travaillé. Le présent article n’impose pas une lettre recommandée ni une procédure de licenciement pour mettre fin à l’essai."),"Le renvoi à la computation du licenciement ne doit pas imposer une lettre recommandée à la rupture d’essai ; la notification probante et les quinze jours entiers sont rendus autonomes, sans changer le reliquat payé.")
# Pure typo, separate from the substantive candidates.
fix('L1221-19',by['L1221-19']['proposed_xml'].replace('s’appliquent à les contrats','s’appliquent aux contrats'),"Correction grammaticale uniquement ; aucun paramètre d’essai ou de préavis n’est modifié.")
# Preserve an explicit safeguard already present in the old accepted proposal.
fix('L1221-21',by['L1221-21']['proposed_xml']+"<p>Pour ces seuls contrats antérieurs, la faculté de renouvellement doit avoir été expressément stipulée dans la lettre d’engagement ou le contrat de travail et sa mise en œuvre reste subordonnée à l’accord exprès du salarié. La seule clause de renouvellement ne vaut pas consentement à son exercice.</p>","La garantie d’accord exprès au renouvellement effectif figurait dans l’avant-image ; elle est maintenue dans la règle, au lieu de demeurer dans les seules notes de L1221-23.")
(P/'corrected-answer.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
expected=[copy.deepcopy(sources[r['number']])for r in out]
for x in expected:x['audited_candidate_sha256']=hashlib.sha256(by[x['number']]['proposed_xml'].encode()).hexdigest()
(P/'corrected-source.json').write_text(json.dumps(expected,ensure_ascii=False,indent=2)+'\n')
print([r['number']for r in out])
